'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),rp=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n||0);const L=window.THLaundryLabel,UI=window.THLaundryUI;let assignees=[],rooms=[],orders=[],member,selected,detail,tab='orders',pageCursor='',nextCursor,stream,busy=false;let loading=false,lastRooms=0;let filter={start:'',end:'',search:'',status:''};
const field=(name,label,type='text',value='',required=true)=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;
const choice=(name,label,items,value='')=>`<label>${label}<select name="${name}">${items.map(v=>{const [id,text]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`}).join('')}</select></label>`;
function msg(text,error=false){$('#message').className='alert '+(error?'error':'success');$('#message').textContent=text;}
async function api(path,data){const r=await fetch('/api/laundry/'+path,{method:data?'POST':'GET',credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(20000),headers:data instanceof FormData?{'X-Top-Hills':'1'}:{'Content-Type':'application/json','X-Top-Hills':'1'},body:data instanceof FormData?data:data?JSON.stringify(data):undefined});const v=await r.json();if(!r.ok){if(r.status===401){$('#view').innerHTML='<h1>Masuk sebagai petugas.</h1><p>Masuk menggunakan akun tim Anda. Owner memberikan peran Operator/Finance setelah akun terdaftar di dashboard utama.</p><a class="button primary" href="/login">Masuk ke Top Hills</a>'; }throw Error(v.error||'Penyimpanan gagal.');}return v;}
function dialog(title,body,submit){
 const modal=$('#modal');modal.innerHTML=`<h2>${esc(title)}</h2><form id="modal-form" class="grid">${body}<p id="modal-message" class="alert danger full" role="alert" hidden></p><div class="full row dialog-footer"><button class="primary" type="submit">Simpan</button><button type="button" id="close">Batal</button></div></form>`;
 modal.showModal();$('#close').onclick=()=>modal.close();const form=$('#modal-form');UI.bindPicker(form);UI.bindWeigh(form);
 form.onsubmit=async e=>{e.preventDefault();if(busy)return;const btn=e.submitter;btn.disabled=true;busy=true;const out=$('#modal-message');out.hidden=true;
 try{await submit(UI.serialize(form));modal.close();}catch(error){out.textContent=error.message;out.hidden=false;out.scrollIntoView({block:'nearest'});}finally{btn.disabled=false;busy=false;}};
}

async function load(force=true){if(loading)return;loading=true;try{if(!member||Date.now()-lastRooms>60000){const r=await api('rooms');rooms=r.rooms;member=r.member;assignees=r.assignees||[];lastRooms=Date.now();if(!rooms.length&&member.role==='Owner'){await api('rooms/init',{});rooms=(await api('rooms')).rooms;}}if(selected){await openOrder(selected);return;}const query=new URLSearchParams({...filter,cursor:pageCursor});const v=await api('orders?'+query);const unchanged=JSON.stringify(orders)===JSON.stringify(v.orders)&&nextCursor===v.nextCursor;orders=v.orders;nextCursor=v.nextCursor;if(force||tab==='rooms'||!unchanged||!$('#tab-orders'))render();}catch(e){msg(e.name==='TimeoutError'?'Koneksi lambat. Data belum diperbarui.':e.message,true);}finally{loading=false;}}

function render(){if(selected)return openOrder(selected);const shown=orders.filter(o=>(!filter.search||JSON.stringify([o.id,o.customer.name,o.room.id]).toLowerCase().includes(filter.search.toLowerCase()))&&(!filter.status||o.status===filter.status)).sort((a,b)=>Number(b.alerts.some(x=>x.includes('checkout')))-Number(a.alerts.some(x=>x.includes('checkout')))||b.alerts.length-a.alerts.length);$('#view').innerHTML=`<div class="row spread desk-heading"><div><span class="eyebrow">Ruang kerja ${esc(member.role)}</span><h1>Meja laundry</h1><p class="muted">Periksa antrean, timbang paket, lalu lanjutkan pekerjaan.</p></div><button class="primary" id="assisted">+ Check-in dibantu</button></div><div class="row"><button id="tab-orders" class="${tab==='orders'?'primary':''}">Antrean order</button>${member.role==='Owner'?`<button id="tab-rooms" class="${tab==='rooms'?'primary':''}">Kamar & QR</button>`:''}<button id="closing">Review & handover shift</button><a class="button" href="/demo">Coba QR demo</a><a class="button" href="/sop-coverage">Cakupan SOP v0.4</a><button id="reload">Perbarui</button></div><p class="muted">QRIS & WhatsApp belum aktif. Untuk pencatatan keuangan, buka Laporan → Deteksi sumber lalu periksa usulannya.</p>${tab==='rooms'?roomTable():`<div class="metrics"><div class="metric"><small>Dalam halaman ini</small><b>${orders.length}</b>order</div><div class="metric"><small>Perlu perhatian</small><b>${orders.filter(o=>o.alerts.length).length}</b>order</div><div class="metric"><small>Identitas belum jelas</small><b>${orders.filter(o=>o.identity!=='CONFIRMED'&&o.status!=='LINKED').length}</b>THL / INT</div><div class="metric"><small>Belum selesai setoran</small><b>${orders.filter(o=>!['MATCHED','NOT CREATED'].includes(o.set.status)).length}</b>settlement</div></div><form class="toolbar" id="filters">${field('start','Dari tanggal','date',filter.start,false)}${field('end','Sampai tanggal','date',filter.end,false)}${field('search','Cari order / nama / kamar','search',filter.search,false)}${choice('status','Tahap', [['','Semua tahap'],...['SUBMITTED','AWAITING PICKUP','AWAITING DROPOFF','PICKED UP','RECEIVED AT COUNTER','QUARANTINE','PRICE CONFIRMATION PENDING','IN PROCESS','READY FOR HANDOVER','COMPLETED','CANCELLED','ON HOLD'].map(x=>[x,L(x)])],filter.status)}<button>Terapkan</button></form><div class="table-wrap"><table><thead><tr><th>ORDER / PELANGGAN</th><th>KAMAR</th><th>BARANG & IDENTITAS</th><th>PEMBAYARAN</th><th>PERHATIAN</th><th></th></tr></thead><tbody>${shown.map(o=>`<tr><td><strong>${esc(o.id)}</strong>${esc(o.customer.name||'Identitas belum lengkap')}<br><small>${new Date(o.createdAt).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})}</small></td><td>${esc(o.room.id)}<br><small>Lantai ${esc(o.room.floor||'—')}</small></td><td>${UI.badge(o.status)}<br>${UI.badge(o.identity)}</td><td>${rp(o.price?.total)}<br>${UI.badge(o.pay.status)}<br><small>Setoran: ${esc(L(o.set.status))}</small></td><td>${o.alerts.map(UI.alert).join('')||UI.badge('CLEAR','Tidak ada kendala')}</td><td><button data-open="${esc(o.id)}">Buka</button></td></tr>`).join('')}</tbody></table>${!shown.length?'<div class="empty">Belum ada pesanan pada rentang ini.<br>Pesanan QR akan masuk otomatis di sini.</div>':''}</div>${nextCursor?'<button id="next">Halaman berikutnya</button>':''}${pageCursor?'<button id="first">Kembali halaman pertama</button>':''}`}`;
 $('#closing').onclick=closing;$('#reload').onclick=load;$('#tab-orders').onclick=()=>{tab='orders';render()};$('#tab-rooms')?.addEventListener('click',()=>{tab='rooms';render()});$('#assisted').onclick=assisted;$('#filters')?.addEventListener('submit',e=>{e.preventDefault();filter={...filter,...Object.fromEntries(new FormData(e.target))};pageCursor='';load()});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{selected=b.dataset.open;openOrder(selected)});document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>editRoom(b.dataset.room));$('#next')?.addEventListener('click',()=>{pageCursor=nextCursor;load()});$('#first')?.addEventListener('click',()=>{pageCursor='';load()});}
function roomTable(){return `<div class="alert">117 kamar dari SOP. Isi lantai dan jenis kamar sesuai kondisi nyata sebelum mengaktifkan QR. Kode QR tidak ditampilkan dalam daftar publik. Rotasi QR membuat QR lama tidak berlaku.</div><div class="table-wrap"><table><thead><tr><th>KAMAR</th><th>LANTAI / JENIS</th><th>CHECKOUT</th><th>STATUS</th><th></th></tr></thead><tbody>${rooms.map(r=>`<tr><td><strong>${esc(r.id)}</strong>Gedung ${esc(r.building)}</td><td>${esc(r.floor||'Belum diisi')} · ${esc(r.roomType||r.type)}</td><td>${r.checkout?esc(new Date(r.checkout).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})):'—'}</td><td>${r.active?'Aktif':'Nonaktif'} · QR ${r.hasQR?'tersedia':'belum dibuat'}</td><td><button data-room="${esc(r.id)}">Atur kamar</button></td></tr>`).join('')}</tbody></table></div>`;}
function showLink(path,title,qr=false){$('#modal').innerHTML=`<h2>${esc(title)}</h2><p>Tautan ini bersifat pribadi. ${qr?'Tempel QR hanya pada kamar yang sesuai.':'Berikan hanya kepada pemilik order.'}</p>${qr?'<canvas id="qr" class="qr"></canvas>':''}<div class="row"><a class="button primary" target="_blank" rel="noreferrer" href="${esc(path)}">Buka halaman</a><button id="copy-link">Salin tautan</button>${qr?'<button id="download-qr">Unduh QR</button>':''}<button id="dismiss">Tutup</button></div>`;$('#modal').showModal();const full=location.origin+path;if(qr){makeRoomQR($('#qr'),full);$('#download-qr').onclick=()=>{const a=document.createElement('a');a.href=$('#qr').toDataURL();a.download='Top-Hills-QR.png';a.click()};}$('#copy-link').onclick=()=>navigator.clipboard.writeText(full).then(()=>msg('Tautan disalin.'));$('#dismiss').onclick=()=>$('#modal').close();}
function editRoom(id){const r=rooms.find(x=>x.id===id);dialog('Kamar '+id,field('floor','Lantai','text',r.floor)+field('roomType','Jenis kamar','text',r.roomType)+field('checkout','Checkout (penginapan)','datetime-local',r.checkout?new Date(Date.parse(r.checkout)+7*3600000).toISOString().slice(0,16):'',false)+`<label class="check"><input type="checkbox" name="active" ${r.active?'checked':''}>Kamar aktif</label><label class="check full"><input type="checkbox" name="rotate">Buat / ganti QR kamar</label>`,async p=>{const v=await api('room',{...p,id,revision:r.revision,active:p.active==='on',rotate:p.rotate==='on',checkout:p.checkout?p.checkout+':00+07:00':''});lastRooms=0;await load();if(v.qrPath)setTimeout(()=>showLink(v.qrPath,'QR kamar '+id,true),30)});}
function assisted(){dialog('Check-in dibantu petugas',choice('roomId','Kamar',[['UNKNOWN','Belum diketahui → INT'],...rooms.filter(r=>r.active).map(r=>[r.id,r.id+' · lantai '+r.floor])])+field('name','Nama (boleh belum diketahui)','text','',false)+field('contact','WhatsApp (boleh belum diketahui)','tel','',false)+choice('relationship','Hubungan',['Penghuni','Tamu','Keluarga'])+choice('method','Metode',[['dropoff','Antar ke counter'],['pickup','Jemput kamar']])+UI.picker(THServices.catalog(),{})+`<p class="alert full">Setelah dibuat, segera ambil foto langsung, catat kantong, lokasi, dan label. Identitas belum lengkap tidak boleh dibayar atau diproses.</p>`,async p=>{const v=await api('assisted',{...p,mutationId:crypto.randomUUID()});selected=v.order.id;await openOrder(selected);setTimeout(()=>showLink(v.trackingPath,'Konfirmasi pelanggan'),30)});}
const actionLabels={'resume':'Lanjutkan tahap sebelumnya','refund-reconcile':'Cocokkan pengembalian dana','assign':'Tugaskan petugas','incident':'Catat kendala / sengketa','set-process-policy':'Atur pembayaran sebelum proses','accept':'Terima order / revisi','receive':'Terima barang & label','confirm-identity':'Verifikasi identitas (Owner)','weigh':'Isi / koreksi timbangan','approve-price':'Catat persetujuan harga','create-pay':'Buat PAY','payment-proof':'Ajukan bukti pembayaran','verify-pay':'Verifikasi penerimaan','submit-set':'Ajukan setoran','approve-set':'Periksa setoran','process':'Mulai proses laundry','ready':'QC: siap diserahkan','handover':'Serahkan ke pelanggan','cancel':'Ajukan pembatalan','approve-cancel':'Putuskan pembatalan','return':'Kembalikan barang','refund-approve':'Setujui refund','refund-pay':'Catat pengembalian dana','paylater':'Izinkan bayar nanti','label-lost':'Laporkan label hilang','relabel':'Foto label pengganti','hold':'Tahan order','void':'Void tanpa menghapus','notify-retry':'Antrekan ulang notifikasi','expire-pay':'Tandai PAY kedaluwarsa','resolve-exception':'Tutup pengecualian'};
function available(o){let a=[];if(!['COMPLETED','CANCELLED','VOIDED','LINKED'].includes(o.status)){a.push('assign');if(o.kind==='THL'&&(!o.acceptedBy||o.acceptedRevision<o.customerRevision))a.push('accept');if(!o.custody)a.push('receive');if(o.identity!=='CONFIRMED'&&member.role==='Owner'&&o.kind==='THL')a.push('confirm-identity');if(o.custody&&o.label&&o.kind==='THL'&&o.acceptedRevision===o.customerRevision&&['PICKED UP','RECEIVED AT COUNTER','PRICE CONFIRMATION PENDING'].includes(o.status)&&!o.pay.received)a.push('weigh');if(o.price&&!o.priceApproved&&o.identity==='CONFIRMED'&&o.acceptedRevision===o.customerRevision)a.push('approve-price');if(o.priceApproved&&!['PAID','OVERPAID'].includes(o.pay.status))a.push('create-pay');if(['PENDING','PENDING VERIFICATION','UNDERPAID'].includes(o.pay.status))a.push('payment-proof','verify-pay','expire-pay');if(o.price&&o.identity==='CONFIRMED'&&o.acceptedRevision===o.customerRevision&&o.custody&&o.label&&o.status==='PRICE CONFIRMATION PENDING')a.push('process');if(o.status==='IN PROCESS')a.push('ready');if(o.status==='READY FOR HANDOVER'&&o.priceApproved&&(o.pay.status==='PAID'||o.paylater))a.push('handover');if(o.status==='CANCEL REQUESTED')a.push('approve-cancel');if(o.status==='RETURN REQUESTED')a.push('return');a.push('cancel','hold');if(o.custody)a.push(o.label?'label-lost':'relabel');if(member.role==='Owner')a.push('paylater','void','set-process-policy');}if(['IN TRANSIT','SHORT','OVER'].includes(o.set.status))a.push('submit-set');if(o.set.status==='PENDING VERIFICATION'&&member.role!=='Operator')a.push('approve-set');if(o.ref.status==='REQUESTED'&&member.role==='Owner')a.push('refund-approve');if(['APPROVED','PARTIALLY REFUNDED'].includes(o.ref.status)&&member.role!=='Operator')a.push('refund-pay');if(o.exceptions.some(e=>e.open)&&member.role==='Owner')a.push('resolve-exception');if(o.ref.status==='REFUNDED'&&o.ref.settlementAdjustment?.status==='REQUIRES RECONCILIATION'&&member.role!=='Operator')a.push('refund-reconcile');if(o.status==='ON HOLD')a=a.filter(x=>['assign','cancel','relabel','label-lost','resolve-exception','submit-set','approve-set','refund-approve','refund-pay','refund-reconcile'].includes(x)).concat('resume');if(['CANCEL REQUESTED','RETURN REQUESTED'].includes(o.status))a=a.filter(x=>['assign','approve-cancel','return','refund-approve','refund-pay','refund-reconcile','resolve-exception','submit-set','approve-set'].includes(x));if(o.status==='COMPLETED'&&o.priceApproved&&!['PAID','OVERPAID'].includes(o.pay.status))a.push('create-pay');if(o.status==='COMPLETED'&&['PENDING','PENDING VERIFICATION','UNDERPAID'].includes(o.pay.status))a.push('payment-proof','verify-pay');a.push('notify-retry','incident');if(member.role==='Finance')a=a.filter(x=>['payment-proof','verify-pay','submit-set','approve-set','refund-pay','refund-reconcile','notify-retry'].includes(x));return [...new Set(a)];}
async function openOrder(id){try{detail=await api('order?id='+encodeURIComponent(id));const o=detail.order;$('#view').innerHTML=`<button id="back">← Antrean order</button><div class="row spread" style="margin:24px 0"><div><span class="eyebrow">${esc(o.intakeSource==='staff_unidentified'?'Intake tanpa identitas':o.createdSource)}</span><h1 style="font-size:28px">${esc(o.id)}</h1><p>${esc(o.customer.name||'Identitas belum diketahui')} · ${esc(o.customer.contact||'WhatsApp belum diisi')}</p></div><button id="tracking">Tautan konfirmasi pelanggan</button></div><div class="detail"><div><div class="card"><div class="status-grid">${[['Barang',o.status],['Identitas',o.identity],['PAY',o.pay.status],['SET',o.set.status],['REF',o.ref.status],['Rekonsiliasi',o.clear]].map(([k,v])=>`<div><small>${k}</small>${UI.badge(v)}</div>`).join('')}</div><p><strong>Kamar ${esc(o.room.id)}</strong> · Gedung ${esc(o.room.building)} · Lantai ${esc(o.room.floor||'—')}</p><p>Diterima: ${esc(o.acceptedBy?.name||'Belum diterima')} · R${o.acceptedRevision}/R${o.customerRevision}</p><p>Barang ${o.custody?'dalam penguasaan petugas':'belum diterima / sudah diserahkan'} · Label ${o.label?'terpasang':'belum terpasang'}</p>${o.createdSource==='OPERATOR ASSISTED'&&!o.intakeProof?'<p class="alert error">Intake belum lengkap. Ambil foto langsung, lalu catat kantong, lokasi dan waktu barang tiba dalam 5 menit.</p>':''}<h2>Rincian paket</h2>${UI.priceTable(o.price)}${o.price?UI.badge(o.priceApproved?'APPROVED':'PENDING',o.priceApproved?'Harga disetujui pelanggan':'Konfirmasi harga ditunggu'):''}<p>Diterima ${rp(o.pay.received)}</p>${o.processAuthorization&&!o.priceApproved?UI.alert('Proses dimulai oleh '+o.processAuthorization.name+': '+o.processAuthorization.reason):''}${o.alerts.map(UI.alert).join('')}${priceHistory(o)}${o.kind==='INT'&&o.status!=='LINKED'&&member.role==='Owner'?'<button id="link-int">Identifikasi & tautkan INT → THL</button>':''}</div><div class="card"><h2>Bukti order</h2><p class="muted">Foto penerimaan, timbang, dan QC memakai kamera langsung. Unggahan galeri dicatat sebagai unggahan.</p><div class="row"><button id="camera">Ambil foto langsung</button><label class="button">Unggah file<input id="upload" type="file" accept="image/png,image/jpeg,application/pdf" hidden></label></div><div id="camera-box"></div><ul>${detail.proofs.map(p=>`<li><a target="_blank" href="/api/laundry/proof?id=${esc(p.id)}">${esc(p.capture==='live'?'Foto langsung':'Unggahan')} · ${new Date(p.created_at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})}</a></li>`).join('')}</ul></div>${revisionPanel(o)}<details class="card"><summary>Jejak aktivitas</summary><ol class="timeline">${detail.events.map(e=>`<li><strong>${esc(e.action)}</strong><small>${esc(JSON.parse(e.data).actorName||e.actor)} · ${new Date(e.at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})}</small>${esc(JSON.parse(e.data).reason||'')}</li>`).join('')}</ol></details></div><aside class="card next-actions">${actionPanel(o)}</aside></div>`;$('#back').onclick=()=>{selected=null;stopCamera();load()};$('#tracking').onclick=async()=>{try{const v=await api('tracking',{id});showLink(v.trackingPath,'Tautan order baru')}catch(e){msg(e.message,true)}};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actionForm(b.dataset.action));$('#upload').onchange=e=>upload(e.target.files[0],'upload');$('#camera').onclick=camera;$('#link-int')?.addEventListener('click',linkInt);}catch(e){msg(e.message,true)}}
function proofSelect(live=false){const list=detail.proofs.filter(p=>!live||p.capture==='live');return (!list.length?'<p class="alert danger full">Ambil foto langsung pada bagian Bukti order terlebih dahulu.</p>':'')+choice('proofId',live?'Foto langsung untuk tahap ini':'Bukti order',list.map(p=>[p.id,(p.capture==='live'?'Foto langsung':'Unggahan')+' · '+new Date(p.created_at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})]));}
function actionForm(action){const o=detail.order;let body='';const proofActions=['receive','confirm-identity','weigh','approve-price','payment-proof','verify-pay','submit-set','ready','handover','return','refund-pay','refund-reconcile','relabel','resolve-exception','incident'];if(proofActions.includes(action))body+=proofSelect(['receive','weigh','ready','handover','return','relabel'].includes(action));if(['assign','resume','refund-reconcile','cancel','approve-cancel','refund-approve','paylater','label-lost','hold','void','resolve-exception','confirm-identity'].includes(action))body+=field('reason','Alasan');if(action==='assign')body+=choice('assignedTo','Petugas bertugas',assignees.map(m=>[m.id,m.name]),o.assignedTo);if(action==='incident')body+=choice('type','Jenis kendala',['Pickup gagal / customer tidak ada','Antrean / target melewati checkout','Barang hilang / rusak','Rework setelah selesai','Sengketa pembayaran','Salah rekening / deposit tidak dikenal','Perubahan harga setelah dibayar','Refund gagal / perlu rekonsiliasi','Kendala lainnya'])+field('reason','Kronologi dan tindakan berikutnya')+field('due','Tenggat tindak lanjut','datetime-local','',false);if(action==='set-process-policy')body+=choice('required','Wajib lunas sebelum proses?',[['yes','Ya, wajib lunas'],['no','Boleh sebelum pembayaran']]);if(action==='receive')body+=field('bags','Jumlah kantong','number',1)+field('location','Lokasi penyimpanan')+field('arrivedAt','Waktu barang sebenarnya tiba','datetime-local','',false);if(action==='weigh')body+=UI.weighEditor(o);if(action==='confirm-identity')body+=field('name','Nama pelanggan','text',o.customer.name)+field('contact','WhatsApp','tel',o.customer.contact);if(action==='create-pay')body+=choice('method','Metode',['Cash','Transfer']);if(['verify-pay','refund-pay'].includes(action))body+=field('amount','Nominal rupiah','number',action==='verify-pay'?o.price.total-o.pay.received:o.ref.amount-(o.ref.paid||0))+field('reference','Referensi bank / kuitansi');if(action==='refund-reconcile')body+=field('reference','Referensi bank / kas setelah refund')+field('cashReturned','Cash dari penerimaan belum disetor yang dikembalikan (rupiah)','number',0);if(action==='submit-set')body+=field('actual','Bersih disetor','number',o.set.gross)+field('fee','Biaya','number',0)+field('account','Rekening tujuan')+field('reference','Referensi mutasi');if(action==='process')body+=field('batch','Nomor batch / mesin')+field('scannedId','Pindai / masukkan kode label THL')+(o.priceApproved?'<p class="alert success full">Harga sudah disetujui. Label harus sama dengan order ini.</p>':`<div class="alert warning full">Konfirmasi pelanggan belum masuk. Hubungi pelanggan terlebih dahulu. Jika perlu dilanjutkan, catat dasar keputusan di bawah.</div>${choice('overrideContext','Dasar melanjutkan',[['','Pilih dasar keputusan'],['CUSTOMER_BUSY','Pelanggan sibuk / belum membalas'],['VERBAL_INSTRUCTION','Sudah diminta lanjut secara langsung'],['LONG_WAIT','Sudah menunggu terlalu lama']])}<label class="full">Alasan lengkap<textarea name="reason" required minlength="20" maxlength="1000" placeholder="Tuliskan waktu menunggu, upaya menghubungi, dan mengapa pekerjaan perlu dilanjutkan."></textarea></label><label class="check full"><input type="checkbox" name="proceedWithoutApproval" required>Saya bertanggung jawab memulai proses ini. Konfirmasi harga pelanggan tetap ditunggu.</label>`);if(['handover','return'].includes(action))body+=field('recipient','Nama penerima');if(action==='resolve-exception')body+=choice('exceptionId','Pengecualian',o.exceptions.filter(e=>e.open).map(e=>[e.id,e.type]));if(!body)body='<p class="full">Konfirmasi tindakan untuk '+esc(o.id)+'.</p>';dialog(actionLabels[action],body,async p=>{if(p.arrivedAt)p.arrivedAt+=':00+07:00';if(p.due)p.due+=':00+07:00';if(action==='set-process-policy')p.required=p.required==='yes';if(action==='process')p.proceedWithoutApproval=p.proceedWithoutApproval==='on';await api('action',{...p,id:o.id,action,revision:o.revision,mutationId:crypto.randomUUID()});await openOrder(o.id);msg('Perubahan tersimpan.');});document.querySelectorAll('#modal input[type=number]').forEach(i=>{if(!i.hasAttribute('min'))i.min='0';if(!i.hasAttribute('step'))i.step='1'});}
function linkInt(){dialog('Identifikasi barang INT',choice('roomId','Kamar terverifikasi',rooms.filter(r=>r.active).map(r=>r.id))+field('name','Nama pemilik')+field('contact','WhatsApp','tel')+proofSelect()+field('reason','Dasar verifikasi'),async p=>{const v=await api('link-int',{...p,id:selected,revision:detail.order.revision});selected=v.order.id;await openOrder(selected);setTimeout(()=>showLink(v.trackingPath,'Konfirmasi THL'),30)});}
async function upload(file,capture){if(!file)return;try{const f=new FormData();f.set('orderId',selected);f.set('capture',capture);f.set('file',file);await api('proof',f);stopCamera();await openOrder(selected);msg('Bukti tersimpan. Pilih bukti ini saat menjalankan tahap berikutnya.');}catch(e){msg(e.message,true)}}
function stopCamera(){stream?.getTracks().forEach(t=>t.stop());stream=null;}
async function camera(){try{stopCamera();stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});$('#camera-box').innerHTML='<video id="live" autoplay playsinline muted></video><button id="capture" class="primary">Foto & simpan</button><button id="stop-camera">Batal</button>';$('#live').srcObject=stream;$('#stop-camera').onclick=()=>{stopCamera();$('#camera-box').innerHTML=''};$('#capture').onclick=()=>{const v=$('#live'),c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;if(!c.width)return;c.getContext('2d').drawImage(v,0,0);c.toBlob(b=>upload(new File([b],'capture.jpg',{type:'image/jpeg'}),'live'),'image/jpeg',.85)};}catch(e){msg('Kamera belum diizinkan. Izinkan akses kamera di browser. '+e.message,true)}}
$('#modal').addEventListener('close',stopCamera);load();

setInterval(()=>{if(!document.hidden&&!$('#modal').open&&!stream&&!busy&&!document.activeElement?.matches('input,textarea,select')&&tab==='orders')load(false);},15000);

async function closing(){try{tab='closing';const v=await api('summary'),s=v.summary;$('#view').innerHTML=`<button id="back-closing">← Antrean</button><h1 style="margin-top:24px">Review & handover shift</h1><p class="muted">Bandingkan seluruh paket dan cash yang masih dalam penguasaan Top Hills. Rekap tidak hanya mencakup halaman antrean yang sedang dibuka.</p><div class="metrics"><div class="metric"><small>Paket menurut sistem</small><b>${s.physicalBags||0}</b>kantong THL + INT</div><div class="metric"><small>Cash belum matched</small><b style="font-size:21px">${rp(s.cashInTransit)}</b>uang penerimaan</div><div class="metric"><small>INT terbuka</small><b>${s.openInt||0}</b>perlu identifikasi</div><div class="metric"><small>Assisted / seluruh order</small><b>${s.assisted||0} / ${s.total||0}</b>${s.accepted||0} sudah diterima</div></div><form class="card grid" id="shift-form">${field('physicalBags','Hasil hitung kantong fisik','number',0)}${field('cash','Hasil hitung cash (rupiah)','number',0)}<label class="full">Catatan handover & tindakan berikutnya<textarea name="note" required minlength="5"></textarea></label><label class="full">Bukti hitung/serah terima<input name="proof" type="file" accept="image/jpeg,image/png,application/pdf" required></label><button class="primary">Ajukan review shift</button></form><div class="card"><h2>Riwayat review</h2>${v.shifts.map(x=>{const d=JSON.parse(x.data);return `<div class="card"><strong>${esc(x.action)} · ${esc(d.actorName||x.actor)}</strong><p>${new Date(x.at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})} · ${esc(d.status)}</p>${d.bagDifference!==undefined?`<p>Selisih paket ${d.bagDifference} · Selisih cash ${rp(d.cashDifference)}</p>`:''}<p>${esc(d.note)}</p>${member.role==='Owner'&&x.action==='SHIFT SUBMITTED'&&!v.shifts.some(r=>r.action==='SHIFT REVIEWED'&&JSON.parse(r.data).sourceId===x.id)?`<button data-review-shift="${esc(x.id)}">Periksa laporan</button>`:''}</div>`}).join('')||'<p>Belum ada handover shift.</p>'}</div>`;$('#back-closing').onclick=()=>{tab='orders';load()};$('#shift-form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;try{const f=new FormData(e.target),proof=new FormData();proof.set('orderId','SHIFT-'+crypto.randomUUID());proof.set('file',f.get('proof'));const uploaded=await api('proof',proof);await api('shift',{physicalBags:f.get('physicalBags'),cash:f.get('cash'),note:f.get('note'),proofId:uploaded.id,mutationId:crypto.randomUUID()});await closing();msg('Handover shift tersimpan untuk review. Selisih tetap terlihat.');}catch(e){msg(e.message,true)}finally{btn.disabled=false}};document.querySelectorAll('[data-review-shift]').forEach(b=>b.onclick=()=>dialog('Review handover shift',field('note','Hasil pemeriksaan'),async p=>{await api('shift-review',{id:b.dataset.reviewShift,...p});await closing()}));}catch(e){msg(e.message,true)}}

window.addEventListener('online',()=>{msg('Koneksi kembali. Mengambil data terbaru.');if(!$('#modal').open)load();});window.addEventListener('offline',()=>msg('Anda offline. Tunggu koneksi sebelum menyimpan.',true));

function revisionPanel(o){
 const labels={name:'Nama',contact:'WhatsApp',relationship:'Hubungan',method:'Penyerahan',serviceIds:'Paket laundry',note:'Instruksi'};
 const pretty=(key,c)=>key==='method'?({pickup:'Jemput kamar',dropoff:'Antar counter'}[c?.method]||c?.method):key==='serviceIds'?UI.ids(c).map(id=>THServices.catalog().find(s=>s.id===id)?.name||id).join(' + '):c?.[key];
 return `<details class="card" ${o.customerRevision>o.acceptedRevision?'open':''}><summary>Revisi pelanggan · R${o.customerRevision}</summary><div class="table-wrap"><table><thead><tr><th>Informasi</th><th>Awal (R1)</th><th>Terbaru (R${o.customerRevision})</th></tr></thead><tbody>${Object.entries(labels).map(([key,label])=>{const a=pretty(key,o.initialSnapshot),b=pretty(key,o.customer);return `<tr><td>${label}</td><td>${esc(a||'—')}</td><td>${esc(b||'—')}${a!==b?' <span class="status-badge warning">Berubah</span>':''}</td></tr>`}).join('')}</tbody></table></div><p class="muted">${o.revisionHistory?.length||0} revisi sebelumnya tersimpan. Penerimaan terbaru: R${o.acceptedRevision}.</p></details>`;
}
function priceHistory(o){return o.priceHistory?.length?`<details><summary>Riwayat koreksi timbang (${o.priceHistory.length})</summary>${[...o.priceHistory].reverse().map(h=>`<div class="history-entry"><p><strong>${esc(h.name)}</strong> · ${new Date(h.at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})}</p><p>${esc(h.reason)}</p>${UI.priceTable(h.price)}</div>`).join('')}</details>`:'';}
function actionPanel(o){
 const g=UI.guidance(o),actions=available(o),primary=actions.includes(g.primary)?g.primary:null;
 const payment=['create-pay','payment-proof','verify-pay','expire-pay','submit-set','approve-set','refund-approve','refund-pay','refund-reconcile','paylater'];
 const routine=['accept','receive','confirm-identity','weigh','approve-price','process','ready','handover','return','approve-cancel','resume'];
 const button=a=>`<button data-action="${a}" class="${a===primary?'primary':a==='process'&&!o.priceApproved?'warning':['cancel','hold','void','label-lost'].includes(a)?'danger':''}">${a==='process'&&!o.priceApproved?'Lanjut dengan alasan':a==='weigh'&&o.price?'Koreksi hasil timbang':actionLabels[a]}</button>`;
 return `<span class="eyebrow">Langkah berikutnya</span><h2>${esc(g.title)}</h2><p class="alert ${g.tone}">${UI.icon(g.tone)}<span>${esc(g.text)}</span></p><div class="actions">${primary?button(primary):''}${actions.filter(a=>a!==primary&&routine.includes(a)).map(button).join('')}</div>${actions.some(a=>payment.includes(a))?`<details open><summary>Pembayaran & setoran</summary><div class="actions">${actions.filter(a=>a!==primary&&payment.includes(a)).map(button).join('')}</div></details>`:''}<details><summary>Tugas & penanganan kendala</summary><div class="actions">${actions.filter(a=>a!==primary&&!routine.includes(a)&&!payment.includes(a)).map(button).join('')}</div></details><p class="muted">Setiap perubahan tercatat atas nama akun Anda.</p>`;
}
